-- A 2-entry pipeline FIFO. `deq` runs first, then `enq`: enq sees the slot
-- that deq just freed, so even a full FIFO accepts an item in the cycle it
-- delivers one. Both rules write count, so they are chained, not parallel.
xblue module mkPipeFifo2;
  input Bool reset;
  input Bool enq_valid;
  input Bit#(8) enq_data;
  input Bool deq_ready;

  Reg#(Vector#(2, Bit#(8))) data <- mkReg(0);
  Reg#(Bit#(1)) wp <- mkReg(0);
  Reg#(Bit#(1)) rp <- mkReg(0);
  Reg#(Bit#(2)) count <- mkReg(0);

  -- what the caller sees at the start of the cycle
  method Bool    enq_ready = count != 2 || deq_ready;
  method Bool    deq_valid = count != 0;
  method Bit#(8) deq_data  = data[rp];

  rule deq (deq_ready && count != 0);
    rp <= rp + 1;
    count <= count - 1;
  endrule

  -- count is read after deq has run: a full FIFO has room again
  rule enq (enq_valid && count != 2);
    data[wp] <= enq_data;
    wp <= wp + 1;
    count <= count + 1;
  endrule

  rule clear (reset);
    wp <= 0;
    rp <= 0;
    count <= 0;
  endrule

  schedule deq ≫ enq ≫ clear;
endmodule
-- ---------------------------------------------------------------- reasoning
open XBlue

structure Regs where
  data : BitVec 16
  wp : BitVec 1
  rp : BitVec 1
  count : BitVec 2

/-- The registers after one clock cycle of the design itself. -/
def next (reset enq : BitVec 1) (x : BitVec 8) (deq : BitVec 1) (s : Regs) : Regs :=
  let t := mkPipeFifo2.design.cycle (.cons reset (.cons enq (.cons x (.cons deq .nil))))
              (.cons s.data (.cons s.wp (.cons s.rp (.cons s.count .nil))))
  ⟨t.regs.get mkPipeFifo2.data, t.regs.get mkPipeFifo2.wp, t.regs.get mkPipeFifo2.rp,
    t.regs.get mkPipeFifo2.count⟩

/-- Write `x` into slot `i` of the packed 2 x 8-bit vector. -/
def put (d : BitVec 16) (i : BitVec 1) (x : BitVec 8) : BitVec 16 :=
  (if i = 1#1 then x else d.extractLsb' 8 8) ++ (if i = 0#1 then x else d.extractLsb' 0 8)

-- One plain function per rule.
def deqStep (deq : BitVec 1) (s : Regs) : Regs :=
  let fires := deq = 1#1 ∧ s.count ≠ 0#2
  ⟨s.data, s.wp, if fires then s.rp + 1#1 else s.rp, if fires then s.count - 1#2 else s.count⟩
def enqStep (enq : BitVec 1) (x : BitVec 8) (s : Regs) : Regs :=
  let fires := enq = 1#1 ∧ s.count ≠ 2#2      -- s.count is what deq left
  ⟨if fires then put s.data s.wp x else s.data, if fires then s.wp + 1#1 else s.wp, s.rp,
    if fires then s.count + 1#2 else s.count⟩
def clearStep (reset : BitVec 1) (s : Regs) : Regs :=
  ⟨s.data, if reset = 1#1 then 0#1 else s.wp, if reset = 1#1 then 0#1 else s.rp,
    if reset = 1#1 then 0#2 else s.count⟩

/-- The cycle is the schedule `deq ≫ enq ≫ clear`, one rule after another. -/
theorem next_eq_steps (reset enq : BitVec 1) (x : BitVec 8) (deq : BitVec 1) (s : Regs) :
    next reset enq x deq s = clearStep reset (enqStep enq x (deqStep deq s)) := by
  obtain ⟨d, wp, rp, c⟩ := s
  -- unfold the design's cycle
  simp [next, mkPipeFifo2.design, Design.cycle, mkPipeFifo2.schedule, mkPipeFifo2.interfaces,
    mkPipeFifo2.rules.deq, mkPipeFifo2.rules.enq, mkPipeFifo2.rules.clear, mkPipeFifo2.signature,
    Sched.run, Action.step, Action.fires, writesIf, State.write, State.cur, State.read, HList.set,
    HList.get, Expr.eval, Expr.binVal, Expr.cmpVal, Common.putR, Common.putW, Common.memAt,
    Common.zeros, mkPipeFifo2.data, mkPipeFifo2.wp, mkPipeFifo2.rp, mkPipeFifo2.count,
    mkPipeFifo2.reset, mkPipeFifo2.enq_valid, mkPipeFifo2.enq_data, mkPipeFifo2.deq_ready,
    mkPipeFifo2.enq_ready, mkPipeFifo2.deq_valid, mkPipeFifo2.deq_data, sliceWidth]
  -- name the three rules
  simp only [deqStep, enqStep, clearStep, put]
  simp
  bv_decide

/-- A full FIFO that dequeues also accepts: it is full again afterwards. -/
theorem full_accepts_while_delivering (x : BitVec 8) (s : Regs) (hfull : s.count = 2#2) :
    (next 0#1 1#1 x 1#1 s).count = 2#2 := by
  rw [next_eq_steps]
  simp only [deqStep, enqStep, clearStep, hfull]
  simp

/-- A full FIFO that is not dequeued refuses: nothing changes. -/
theorem full_refuses (x : BitVec 8) (s : Regs) (hfull : s.count = 2#2) :
    next 0#1 1#1 x 0#1 s = s := by
  rw [next_eq_steps]
  obtain ⟨d, wp, rp, c⟩ := s
  simp only [deqStep, enqStep, clearStep] at *
  simp [hfull]

