  simp [next, mkPipeFifo2.design, Design.cycle, mkPipeFifo2.schedule, mkPipeFifo2.interfaces,
    mkPipeFifo2.rules.deq, mkPipeFifo2.rules.enq, mkPipeFifo2.rules.clear, mkPipeFifo2.signature,
    Sched.run, Action.step, Action.fires, writesIf, State.write, State.cur, State.read, HList.set,
    HList.get, Expr.eval, Expr.binVal, Expr.cmpVal, Common.putR, Common.putW, Common.memAt,
    Common.zeros, mkPipeFifo2.data, mkPipeFifo2.wp, mkPipeFifo2.rp, mkPipeFifo2.count,
    mkPipeFifo2.reset, mkPipeFifo2.enq_valid, mkPipeFifo2.enq_data, mkPipeFifo2.deq_ready,
    mkPipeFifo2.enq_ready, mkPipeFifo2.deq_valid, mkPipeFifo2.deq_data, sliceWidth]
  -- name the three rules
  simp only [deqStep, enqStep, clearStep, put]
  simp
  bv_decide

/-- A full FIFO that dequeues also accepts: it is full again afterwards. -/
theorem full_accepts_while_delivering (x : BitVec 8) (s : Regs) (hfull : s.count = 2#2) :
    (next 0#1 1#1 x 1#1 s).count = 2#2 := by
  rw [next_eq_steps]
  simp only [deqStep, enqStep, clearStep, hfull]
  simp

/-- A full FIFO that is not dequeued refuses: nothing changes. -/
theorem full_refuses (x : BitVec 8) (s : Regs) (hfull : s.count = 2#2) :
    next 0#1 1#1 x 0#1 s = s := by
  rw [next_eq_steps]
  obtain ⟨d, wp, rp, c⟩ := s
  simp only [deqStep, enqStep, clearStep] at *
  simp [hfull]

